  }

  static const fb.Reader<ppsTelemetry> reader = _ppsTelemetryReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  ///  Number of samples; every per-sample series has this many entries (three
  ///  or four times as many for vectors).
  int get SAMPLE_COUNT => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 4, 0);
  int get sampleCount => SAMPLE_COUNT;
  ///  Seconds from the scenario start, one per sample.
  List<double>? get ELAPSED_S => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 6);
  List<double>? get elapsedS => ELAPSED_S;
  ///  Active pointing mode.
  List<ppsAttitudeMode>? get MODE => const fb.ListReader<ppsAttitudeMode>(ppsAttitudeMode.reader).vTableGetNullable(_bc, _bcOffset, 8);
  ///  Pointing error, deg.
  List<double>? get POINTING_ERROR_DEG => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 10);
  List<double>? get pointingErrorDeg => POINTING_ERROR_DEG;
