  List<double>? get bodyRateDegS => BODY_RATE_DEG_S;
  ///  Body angular velocity in body axes, deg/s, 3 per sample.
  List<double>? get BODY_RATE_VECTOR_DEG_S => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 14);
  List<double>? get bodyRateVectorDegS => BODY_RATE_VECTOR_DEG_S;
  ///  Attitude quaternion inertial-to-body, scalar last (q1, q2, q3, qc), 4
  ///  per sample.
  List<double>? get ATTITUDE_QUATERNION => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 16);
  List<double>? get attitudeQuaternion => ATTITUDE_QUATERNION;
  ///  Reaction-wheel momentum magnitude, N m s.
  List<double>? get WHEEL_MOMENTUM_NMS => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 18);
  List<double>? get wheelMomentumNms => WHEEL_MOMENTUM_NMS;
  ///  Attitude sensor noise, arcsec, 1 sigma.
  List<double>? get SENSOR_NOISE_ARCSEC => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 20);
  List<double>? get sensorNoiseArcsec => SENSOR_NOISE_ARCSEC;
  ///  Position relative to RELATIVE_TARGET_ID in the target's radial,
  ///  in-track, cross-track axes, m, 3 per sample.
  List<double>? get RELATIVE_POSITION_M => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 22);
  List<double>? get relativePositionM => RELATIVE_POSITION_M;
  ///  Fraction of full sunlight on the array (0 in eclipse, 1 at normal
  ///  incidence with no eclipse), 0-1.
  List<double>? get ILLUMINATION => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 24);
  ///  True while the spacecraft is in eclipse.
  List<bool>? get IN_ECLIPSE => const fb.ListReader<bool>(fb.BoolReader()).vTableGetNullable(_bc, _bcOffset, 26);
  List<bool>? get inEclipse => IN_ECLIPSE;
  ///  Power generated by the array, W.
  List<double>? get GENERATED_POWER_W => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 28);
  List<double>? get generatedPowerW => GENERATED_POWER_W;
  ///  Electrical load, W.
  List<double>? get LOAD_POWER_W => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 30);
  List<double>? get loadPowerW => LOAD_POWER_W;
  ///  Generated minus load, W (positive = charging).
  List<double>? get NET_POWER_W => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 32);
