  List<double>? get batteryEnergyWh => BATTERY_ENERGY_WH;

  @override
  String toString() {
    return 'ppsTelemetry{sampleCount: ${sampleCount}, elapsedS: ${elapsedS}, MODE: ${MODE}, pointingErrorDeg: ${pointingErrorDeg}, bodyRateDegS: ${bodyRateDegS}, bodyRateVectorDegS: ${bodyRateVectorDegS}, attitudeQuaternion: ${attitudeQuaternion}, wheelMomentumNms: ${wheelMomentumNms}, sensorNoiseArcsec: ${sensorNoiseArcsec}, relativePositionM: ${relativePositionM}, ILLUMINATION: ${ILLUMINATION}, inEclipse: ${inEclipse}, generatedPowerW: ${generatedPowerW}, loadPowerW: ${loadPowerW}, netPowerW: ${netPowerW}, batteryStateOfCharge: ${batteryStateOfCharge}, batteryEnergyWh: ${batteryEnergyWh}}';
