        : fbBuilder.writeListFloat64(_BATTERY_STATE_OF_CHARGE!);
    final int? BATTERY_ENERGY_WHOffset = _BATTERY_ENERGY_WH == null ? null
        : fbBuilder.writeListFloat64(_BATTERY_ENERGY_WH!);
    fbBuilder.startTable(17);
    fbBuilder.addUint32(0, _SAMPLE_COUNT);
    fbBuilder.addOffset(1, ELAPSED_SOffset);
    fbBuilder.addOffset(2, MODEOffset);
    fbBuilder.addOffset(3, POINTING_ERROR_DEGOffset);
    fbBuilder.addOffset(4, BODY_RATE_DEG_SOffset);
    fbBuilder.addOffset(5, BODY_RATE_VECTOR_DEG_SOffset);
    fbBuilder.addOffset(6, ATTITUDE_QUATERNIONOffset);
    fbBuilder.addOffset(7, WHEEL_MOMENTUM_NMSOffset);
    fbBuilder.addOffset(8, SENSOR_NOISE_ARCSECOffset);
    fbBuilder.addOffset(9, RELATIVE_POSITION_MOffset);
    fbBuilder.addOffset(10, ILLUMINATIONOffset);
    fbBuilder.addOffset(11, IN_ECLIPSEOffset);
    fbBuilder.addOffset(12, GENERATED_POWER_WOffset);
    fbBuilder.addOffset(13, LOAD_POWER_WOffset);
    fbBuilder.addOffset(14, NET_POWER_WOffset);
    fbBuilder.addOffset(15, BATTERY_STATE_OF_CHARGEOffset);
    fbBuilder.addOffset(16, BATTERY_ENERGY_WHOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
///  Pointing and Power Scenario - a scenario, and the telemetry a run of it
///  produced.
class PPS {
  PPS._(this._bc, this._bcOffset);
  factory PPS(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<PPS> reader = _PPSReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  ///  Identifier of the run; empty = not assigned.
  String? get RUN_ID => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 4);
  String? get runId => RUN_ID;
  ///  Unix milliseconds the run was made.
  int get CREATED_AT_MS => const fb.Int64Reader().vTableGet(_bc, _bcOffset, 6, 0);
  int get createdAtMs => CREATED_AT_MS;
  ///  Identifier of the simulator that ran it.
  String? get PROVIDER => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 8);
  ppsScenario? get SCENARIO => ppsScenario.reader.vTableGetNullable(_bc, _bcOffset, 10);
  ppsStatus get STATUS => ppsStatus.fromValue(const fb.Uint8Reader().vTableGet(_bc, _bcOffset, 12, 0));
  ///  Stable machine-readable reason for InvalidRequest or Failed.
  String? get ERROR_CODE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 14);
  String? get errorCode => ERROR_CODE;
  String? get ERROR_MESSAGE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 16);
  String? get errorMessage => ERROR_MESSAGE;
  ///  Products the telemetry carries.
  List<ppsProduct>? get PRODUCTS => const fb.ListReader<ppsProduct>(ppsProduct.reader).vTableGetNullable(_bc, _bcOffset, 18);
  ///  Modelling assumptions and simplifications of the run, as text.
  List<String>? get ASSUMPTIONS => const fb.ListReader<String>(fb.StringReader()).vTableGetNullable(_bc, _bcOffset, 20);
  ppsTelemetry? get TELEMETRY => ppsTelemetry.reader.vTableGetNullable(_bc, _bcOffset, 22);

  @override
  String toString() {
    return 'PPS{runId: ${runId}, createdAtMs: ${createdAtMs}, PROVIDER: ${PROVIDER}, SCENARIO: ${SCENARIO}, STATUS: ${STATUS}, errorCode: ${errorCode}, errorMessage: ${errorMessage}, PRODUCTS: ${PRODUCTS}, ASSUMPTIONS: ${ASSUMPTIONS}, TELEMETRY: ${TELEMETRY}}';
  }
}

class _PPSReader extends fb.TableReader<PPS> {
  const _PPSReader();

  @override
  PPS createObject(fb.BufferContext bc, int offset) =>
    PPS._(bc, offset);
}

class PPSBuilder {
  PPSBuilder(this.fbBuilder);

  final fb.Builder fbBuilder;

  void begin() {
    fbBuilder.startTable(10);
  }

  int addRunIdOffset(int? offset) {
    fbBuilder.addOffset(0, offset);
    return fbBuilder.offset;
  }
  int addCreatedAtMs(int? CREATED_AT_MS) {
    fbBuilder.addInt64(1, CREATED_AT_MS);
    return fbBuilder.offset;
  }
  int addProviderOffset(int? offset) {
    fbBuilder.addOffset(2, offset);
    return fbBuilder.offset;
  }
  int addScenarioOffset(int? offset) {
    fbBuilder.addOffset(3, offset);
    return fbBuilder.offset;
  }
  int addStatus(ppsStatus? STATUS) {
    fbBuilder.addUint8(4, STATUS?.value);
    return fbBuilder.offset;
  }
  int addErrorCodeOffset(int? offset) {
    fbBuilder.addOffset(5, offset);
    return fbBuilder.offset;
  }
  int addErrorMessageOffset(int? offset) {
    fbBuilder.addOffset(6, offset);
    return fbBuilder.offset;
  }
  int addProductsOffset(int? offset) {
    fbBuilder.addOffset(7, offset);
    return fbBuilder.offset;
  }
  int addAssumptionsOffset(int? offset) {
    fbBuilder.addOffset(8, offset);
    return fbBuilder.offset;
  }
  int addTelemetryOffset(int? offset) {
    fbBuilder.addOffset(9, offset);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
}

class PPSObjectBuilder extends fb.ObjectBuilder {
  final String? _RUN_ID;
  final int? _CREATED_AT_MS;
  final String? _PROVIDER;
  final ppsScenarioObjectBuilder? _SCENARIO;
  final ppsStatus? _STATUS;
  final String? _ERROR_CODE;
  final String? _ERROR_MESSAGE;
  final List<ppsProduct>? _PRODUCTS;
  final List<String>? _ASSUMPTIONS;
  final ppsTelemetryObjectBuilder? _TELEMETRY;

  PPSObjectBuilder({
    String? RUN_ID,
    String? runId,
    int? CREATED_AT_MS,
    int? createdAtMs,
    String? PROVIDER,
    ppsScenarioObjectBuilder? SCENARIO,
    ppsStatus? STATUS,
    String? ERROR_CODE,
    String? errorCode,
    String? ERROR_MESSAGE,
    String? errorMessage,
    List<ppsProduct>? PRODUCTS,
    List<String>? ASSUMPTIONS,
    ppsTelemetryObjectBuilder? TELEMETRY,
  })
      : _RUN_ID = runId ?? RUN_ID,
        _CREATED_AT_MS = createdAtMs ?? CREATED_AT_MS,
        _PROVIDER = PROVIDER,
        _SCENARIO = SCENARIO,
        _STATUS = STATUS,
        _ERROR_CODE = errorCode ?? ERROR_CODE,
        _ERROR_MESSAGE = errorMessage ?? ERROR_MESSAGE,
        _PRODUCTS = PRODUCTS,
        _ASSUMPTIONS = ASSUMPTIONS,
        _TELEMETRY = TELEMETRY;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? RUN_IDOffset = _RUN_ID == null ? null
        : fbBuilder.writeString(_RUN_ID!);
    final int? PROVIDEROffset = _PROVIDER == null ? null
        : fbBuilder.writeString(_PROVIDER!);
    final int? SCENARIOOffset = _SCENARIO?.getOrCreateOffset(fbBuilder);
    final int? ERROR_CODEOffset = _ERROR_CODE == null ? null
        : fbBuilder.writeString(_ERROR_CODE!);
    final int? ERROR_MESSAGEOffset = _ERROR_MESSAGE == null ? null
        : fbBuilder.writeString(_ERROR_MESSAGE!);
    final int? PRODUCTSOffset = _PRODUCTS == null ? null
        : fbBuilder.writeListUint8(_PRODUCTS!.map((f) => f.value).toList());
    final int? ASSUMPTIONSOffset = _ASSUMPTIONS == null ? null
        : fbBuilder.writeList(_ASSUMPTIONS!.map(fbBuilder.writeString).toList());
    final int? TELEMETRYOffset = _TELEMETRY?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(10);
    fbBuilder.addOffset(0, RUN_IDOffset);
    fbBuilder.addInt64(1, _CREATED_AT_MS);
    fbBuilder.addOffset(2, PROVIDEROffset);
    fbBuilder.addOffset(3, SCENARIOOffset);
    fbBuilder.addUint8(4, _STATUS?.value);
    fbBuilder.addOffset(5, ERROR_CODEOffset);
    fbBuilder.addOffset(6, ERROR_MESSAGEOffset);
    fbBuilder.addOffset(7, PRODUCTSOffset);
    fbBuilder.addOffset(8, ASSUMPTIONSOffset);
    fbBuilder.addOffset(9, TELEMETRYOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
